UPDATE trade_order
SET status = 'PAID', paid_at = #{now}
WHERE id = #{id} AND user_id = #{userId}
  AND status = 'PENDING_PAYMENT' AND expires_at > #{now}

UPDATE trade_order
SET status = 'CANCELED', ended_at = #{now}
WHERE id = #{id} AND user_id = #{userId} AND status = 'PENDING_PAYMENT'

mapper.select:
SELECT id FROM trade_order
WHERE status = 'PENDING_PAYMENT' AND expires_at <= #{cutoff}
ORDER BY expires_at, id
LIMIT #{limit}

mapper.update:
UPDATE trade_order
SET status = 'CLOSED', ended_at = #{cutoff}
WHERE id = #{id} AND status = 'PENDING_PAYMENT' AND expires_at <= #{cutoff}
